import{_ as e,o,c as r,a3 as d}from"./chunks/framework.CRbjHCyB.js";const m=JSON.parse('{"title":"运行机制（Runtime）","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"运行机制（Runtime） | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/design/runtime"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/design/runtime"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/runtime"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/runtime"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/runtime"}]]},"headers":[],"relativePath":"zh/catter/design/runtime.md","filePath":"zh/catter/design/runtime.md","lastUpdated":1788608469000}'),a={name:"zh/catter/design/runtime.md"};function i(n,t,c,l,s,h){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="运行机制-runtime" tabindex="-1">运行机制（Runtime） <a class="header-anchor" href="#运行机制-runtime" aria-label="Permalink to &quot;运行机制（Runtime）&quot;">​</a></h1><p>runtime 是 catter 实际捕获进程创建行为的机制。catter 围绕 runtime 展开：脚本不关心命令是如何被捕获的，只关心当前 runtime 提供了什么能力。</p><h2 id="为什么需要多种-runtime" tabindex="-1">为什么需要多种 runtime <a class="header-anchor" href="#为什么需要多种-runtime" aria-label="Permalink to &quot;为什么需要多种 runtime&quot;">​</a></h2><p>&quot;拦截进程创建&quot;在不同平台上的可行性和代价差异很大：</p><ul><li><strong>hook 最全能</strong>，能透明拦截任意子进程创建，但依赖平台特性。例如 macOS 的 <code>DYLD_INSERT_LIBRARIES</code> 受系统保护机制限制、需要特殊开发权限；Windows 没有预加载机制，只能靠 DLL 注入。</li><li><strong>有些场景根本不需要 hook</strong>。构建系统如果遵守 <code>CC</code>/<code>CXX</code> 环境变量约定，直接替换编译器即可捕获全部编译命令。</li><li><strong>有些平台提供了专门的监控 API</strong>，例如 macOS 的 Event Stream / Endpoint Security，可以作为 hook 的替代或补充。</li></ul><p>因此 catter 把捕获机制抽象为 runtime：一个 runtime 就是一种捕获实现，向脚本暴露固定的一组能力描述，脚本基于能力适配行为，而不是假设某个 runtime 一定存在。</p><h2 id="能力模型" tabindex="-1">能力模型 <a class="header-anchor" href="#能力模型" aria-label="Permalink to &quot;能力模型&quot;">​</a></h2><p>脚本在 <code>onStart</code> 收到的 <code>config.runtime</code> 中可以看到当前 runtime 的能力：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>type</code></td><td>runtime 类型：<code>inject</code> / <code>eslogger</code> / <code>env</code></td></tr><tr><td><code>supportActions</code></td><td>支持的脚本动作（<code>skip</code> / <code>drop</code> / <code>abort</code> / <code>modify</code> 的子集）</td></tr><tr><td><code>supportParentId</code></td><td>捕获的命令能否报告父命令 ID（命令树、目标树等功能依赖它）</td></tr></tbody></table><h2 id="机制一览" tabindex="-1">机制一览 <a class="header-anchor" href="#机制一览" aria-label="Permalink to &quot;机制一览&quot;">​</a></h2><h3 id="inject-已实现-默认" tabindex="-1">inject（已实现，默认） <a class="header-anchor" href="#inject-已实现-默认" aria-label="Permalink to &quot;inject（已实现，默认）&quot;">​</a></h3><ul><li><strong>原理</strong>：hook 共享库注入构建系统进程，拦截进程创建调用（Unix 的 <code>execve</code> / <code>posix_spawn</code> 族，Windows 的 <code>CreateProcess</code>），把命令重写为经 <code>catter-proxy</code> 中转后执行。</li><li><strong>平台</strong>：Linux、macOS、Windows。</li><li><strong>能力</strong>：<code>supportActions = [skip, drop, modify]</code>，<code>supportParentId = true</code>。</li><li><strong>特点</strong>：递归捕获——所有子孙进程都会被拦截；脚本看到的命令带有完整环境变量和父命令 ID。</li><li><strong>限制</strong>：实现依赖平台特性（预加载 / DLL 注入）。macOS 上 <code>DYLD_INSERT_LIBRARIES</code> 受系统保护机制限制，需要特殊开发权限；Windows 的 DLL 注入可能与强签名或安全软件策略冲突。</li><li><strong>实现细节</strong>：<a href="./hook-mechanism">钩子机制</a>、<a href="./ipc-protocol">IPC 协议</a>。</li></ul><h3 id="env-规划中" tabindex="-1">env（规划中） <a class="header-anchor" href="#env-规划中" aria-label="Permalink to &quot;env（规划中）&quot;">​</a></h3><ul><li><strong>原理</strong>：通过设置 <code>CC</code> / <code>CXX</code> 等环境变量，把编译器调用重定向到 <code>catter-proxy</code>（包装模式）。</li><li><strong>适用场景</strong>：构建系统遵守标准编译器环境变量约定时，无需 hook 即可捕获编译命令。</li><li><strong>预期限制</strong>：只能捕获经由这些环境变量发起的调用；硬编码编译器路径、内嵌 <code>cc</code> 的构建脚本可能绕过；预期无法报告父命令 ID。</li><li><strong>状态</strong>：尚未实现，具体能力（如 <code>supportActions</code>）待实现后确认。</li></ul><h3 id="eslogger-规划中" tabindex="-1">eslogger（规划中） <a class="header-anchor" href="#eslogger-规划中" aria-label="Permalink to &quot;eslogger（规划中）&quot;">​</a></h3><ul><li><strong>原理</strong>：使用 macOS 的 Event Stream 监控 API 观察进程创建 / 执行事件，属于旁路式监控。</li><li><strong>适用场景</strong>：macOS 上 hook 受权限限制时的替代机制。</li><li><strong>预期限制</strong>：仅限 macOS；依赖系统授予的监控权限；旁路式监听对命令执行的干预能力（如 <code>modify</code> / <code>drop</code>）待实现后确认。</li><li><strong>状态</strong>：尚未实现。</li></ul><h2 id="能力矩阵" tabindex="-1">能力矩阵 <a class="header-anchor" href="#能力矩阵" aria-label="Permalink to &quot;能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>平台</th><th>捕获方式</th><th>supportActions</th><th>supportParentId</th><th>状态</th></tr></thead><tbody><tr><td>inject</td><td>Linux / macOS / Windows</td><td>hook 拦截进程创建</td><td><code>skip</code> <code>drop</code> <code>modify</code></td><td>是</td><td>已实现（默认）</td></tr><tr><td>env</td><td>跨平台</td><td><code>CC</code> / <code>CXX</code> 环境变量</td><td>待定</td><td>预期否</td><td>规划中</td></tr><tr><td>eslogger</td><td>macOS</td><td>Event Stream API</td><td>待定</td><td>待定</td><td>规划中</td></tr></tbody></table><h2 id="选择与检查" tabindex="-1">选择与检查 <a class="header-anchor" href="#选择与检查" aria-label="Permalink to &quot;选择与检查&quot;">​</a></h2><ul><li>默认使用 <code>inject</code>，无需配置；其他机制上线后通过 <code>-m/--mode</code> 选择。</li><li>脚本作者不应假设机制：在 <code>onStart</code> 中检查 <code>config.runtime.supportActions</code>，只使用当前 runtime 支持的动作。</li><li><code>supportParentId = false</code> 时，<code>CommandData.parent</code> 不会出现，依赖父子关系的功能（命令树、目标树）需要降级处理。</li></ul>',20)])])}const p=e(a,[["render",i]]);export{m as __pageData,p as default};
